const inputItems = $input.all();
const seen = new Set();
const cutoff = Date.now() - 24 * 60 * 60 * 1000;
const out = [];

for (const item of inputItems) {
  const j = item.json;
  const title = (j.title || '').toString().trim();
  const link = (j.link || j.guid || '').toString().trim();
  if (!title || !link) continue;

  const key = link.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);

  const pubDate = j.isoDate || j.pubDate || j.date;
  const ts = pubDate ? new Date(pubDate).getTime() : NaN;
  if (isNaN(ts) || ts < cutoff) continue;

  out.push({
    title: title,
    link: link,
    summary: (j.contentSnippet || j.summary || j.content || '').toString().replace(/\s+/g, ' ').trim().slice(0, 400)
  });
}

return [{ json: { items: out.slice(0, 15) } }];

const raw = $input.first().json;
let text;
if (Array.isArray(raw.content)) {
  text = raw.content.map(b => b.text || '').join('\n');
} else {
  text = raw.content || raw.text || raw.output || raw.message || JSON.stringify(raw);
}
if (typeof text !== 'string') text = JSON.stringify(text);

let jsonText = text.trim();
const fenceMatch = jsonText.match(/```(?:json)?\s*([\s\S]*?)```/i);
if (fenceMatch) jsonText = fenceMatch[1].trim();

let ideas;
try {
  ideas = JSON.parse(jsonText);
} catch (e) {
  throw new Error('Could not parse AI response as JSON: ' + e.message + ' | Raw: ' + jsonText.slice(0, 500));
}

const blocks = ideas.map((idea, idx) => {
  const n = idx + 1;
  return '**' + n + '. ' + idea.hook + '**\n_' + idea.angle + '_\n```\n' + idea.full_script + '\n```\nSource: ' + idea.source_link;
});

const header = '**Daily Content Ideas - ' + new Date().toISOString().slice(0, 10) + '**\n\n';
const LIMIT = 1900;
const messages = [];
let current = header;

for (const block of blocks) {
  const candidate = (current === header) ? current + block : current + '\n\n' + block;
  if (candidate.length > LIMIT) {
    if (current.trim().length) messages.push(current);
    current = block;
  } else {
    current = candidate;
  }
}
if (current.trim().length) messages.push(current);

return messages.map(function (content) { return { json: { content: content } }; });
